pragma solidity ^0.8.0;

// Note: the ERC-165 identifier for this interface is 0x897e2c73.
interface IERC6150 /* is IERC721, IERC165 */ {
    /**
     * @notice Emitted when `tokenId` token under `parentId` is minted.
     * @param minter The address of minter
     * @param to The address received token
     * @param parentId The id of parent token, if it's zero, it means minted `tokenId` is a root token.
     * @param tokenId The id of minted token, required to be greater than zero
     */
    event Minted(
        address indexed minter,
        address indexed to,
        uint256 parentId,
        uint256 tokenId
    );

    /**
     * @notice Get the parent token of `tokenId` token.
     * @param tokenId The child token
     * @return parentId The Parent token found
     */
    function parentOf(uint256 tokenId) external view returns (uint256 parentId);

    /**
     * @notice Get the children tokens of `tokenId` token.
     * @param tokenId The parent token
     * @return childrenIds The array of children tokens
     */
    function childrenOf(
        uint256 tokenId
    ) external view returns (uint256[] memory childrenIds);

    /**
     * @notice Check the `tokenId` token if it is a root token.
     * @param tokenId The token want to be checked
     * @return Return `true` if it is a root token; if not, return `false`
     */
    function isRoot(uint256 tokenId) external view returns (bool);

    /**
     * @notice Check the `tokenId` token if it is a leaf token.
     * @param tokenId The token want to be checked
     * @return Return `true` if it is a leaf token; if not, return `false`
     */
    function isLeaf(uint256 tokenId) external view returns (bool);
}
Optional Extension: Enumerable
// Note: the ERC-165 identifier for this interface is 0xba541a2e.
interface IERC6150Enumerable is IERC6150 /* IERC721Enumerable */ {
    /**
     * @notice Get total amount of children tokens under `parentId` token.
     * @dev If `parentId` is zero, it means get total amount of root tokens.
     * @return The total amount of children tokens under `parentId` token.
     */
    function childrenCountOf(uint256 parentId) external view returns (uint256);

    /**
     * @notice Get the token at the specified index of all children tokens under `parentId` token.
     * @dev If `parentId` is zero, it means get root token.
     * @return The token ID at `index` of all chlidren tokens under `parentId` token.
     */
    function childOfParentByIndex(
        uint256 parentId,
        uint256 index
    ) external view returns (uint256);

    /**
     * @notice Get the index position of specified token in the children enumeration under specified parent token.
     * @dev Throws if the `tokenId` is not found in the children enumeration.
     * If `parentId` is zero, means get root token index.
     * @param parentId The parent token
     * @param tokenId The specified token to be found
     * @return The index position of `tokenId` found in the children enumeration
     */
    function indexInChildrenEnumeration(
        uint256 parentId,
        uint256 tokenId
    ) external view returns (uint256);
}
Optional Extension: Burnable
// Note: the ERC-165 identifier for this interface is 0x4ac0aa46.
interface IERC6150Burnable is IERC6150 {
    /**
     * @notice Burn the `tokenId` token.
     * @dev Throws if `tokenId` is not a leaf token.
     * Throws if `tokenId` is not a valid NFT.
     * Throws if `owner` is not the owner of `tokenId` token.
     * Throws unless `msg.sender` is the current owner, an authorized operator, or the approved address for this token.
     * @param tokenId The token to be burnt
     */
    function safeBurn(uint256 tokenId) external;

    /**
     * @notice Batch burn tokens.
     * @dev Throws if one of `tokenIds` is not a leaf token.
     * Throws if one of `tokenIds` is not a valid NFT.
     * Throws if `owner` is not the owner of all `tokenIds` tokens.
     * Throws unless `msg.sender` is the current owner, an authorized operator, or the approved address for all `tokenIds`.
     * @param tokenIds The tokens to be burnt
     */
    function safeBatchBurn(uint256[] memory tokenIds) external;
}
Optional Extension: ParentTransferable
// Note: the ERC-165 identifier for this interface is 0xfa574808.
interface IERC6150ParentTransferable is IERC6150 {
    /**
     * @notice Emitted when the parent of `tokenId` token changed.
     * @param tokenId The token changed
     * @param oldParentId Previous parent token
     * @param newParentId New parent token
     */
    event ParentTransferred(
        uint256 tokenId,
        uint256 oldParentId,
        uint256 newParentId
    );

    /**
     * @notice Transfer parentship of `tokenId` token to a new parent token
     * @param newParentId New parent token id
     * @param tokenId The token to be changed
     */
    function transferParent(uint256 newParentId, uint256 tokenId) external;

    /**
     * @notice Batch transfer parentship of `tokenIds` to a new parent token
     * @param newParentId New parent token id
     * @param tokenIds Array of token ids to be changed
     */
    function batchTransferParent(
        uint256 newParentId,
        uint256[] memory tokenIds
    ) external;
}
Optional Extension: Access Control
// Note: the ERC-165 identifier for this interface is 0x1d04f0b3.
interface IERC6150AccessControl is IERC6150 {
    /**
     * @notice Check the account whether a admin of `tokenId` token.
     * @dev Each token can be set more than one admin. Admin have permission to do something to the token, like mint child token,
     * or burn token, or transfer parentship.
     * @param tokenId The specified token
     * @param account The account to be checked
     * @return If the account has admin permission, return true; otherwise, return false.
     */
    function isAdminOf(uint256 tokenId, address account)
        external
        view
        returns (bool);

    /**
     * @notice Check whether the specified parent token and account can mint children tokens
     * @dev If the `parentId` is zero, check whether account can mint root nodes
     * @param parentId The specified parent token to be checked
     * @param account The specified account to be checked
     * @return If the token and account has mint permission, return true; otherwise, return false.
     */
    function canMintChildren(
        uint256 parentId,
        address account
    ) external view returns (bool);

    /**
     * @notice Check whether the specified token can be burnt by specified account
     * @param tokenId The specified token to be checked
     * @param account The specified account to be checked
     * @return If the tokenId can be burnt by account, return true; otherwise, return false.
     */
    function canBurnTokenByAccount(uint256 tokenId, address account)
        external
        view
        returns (bool);
}"}

{'Main Content': 'The key words “MUST”, “MUST NOT”, “REQUIRED”, “SHALL”, “SHALL NOT”, “SHOULD”, “SHOULD NOT”, “RECOMMENDED”, “MAY”, and “OPTIONAL” in this document are to be interpreted as described in RFC 2119.
/// @title EIP-6454 Minimalistic Non-Transferable interface for NFTs
/// @dev See https://eips.ethereum.org/EIPS/eip-6454
/// @dev Note: the ERC-165 identifier for this interface is 0x91a6262f.

pragma solidity ^0.8.16;

interface IERC6454 /* is IERC165 */ {
    /**
     * @notice Used to check whether the given token is transferable or not.
     * @dev If this function returns `false`, the transfer of the token MUST revert execution.
     * @dev If the tokenId does not exist, this method MUST revert execution, unless the token is being checked for
     *  minting.
     * @dev The `from` parameter MAY be used to also validate the approval of the token for transfer, but anyone
     *  interacting with this function SHOULD NOT rely on it as it is not mandated by the proposal.
     * @param tokenId ID of the token being checked
     * @param from Address from which the token is being transferred
     * @param to Address to which the token is being transferred
     * @return Boolean value indicating whether the given token is transferable
     */
    function isTransferable(uint256 tokenId, address from, address to) external view returns (bool);
}
In order to determine whether a token is transferable or not in general, the function SHOULD return the appropriate boolean value when passing the 0x0000000000000000000000000000000000000000 address as the to and from parameter.
The general transferability of a token should not be affected by the ability to mint the token (value of from parameter is 0x0000000000000000000000000000000000000000) and the ability to burn the token (value of to parameter is 0x0000000000000000000000000000000000000000).
If the general transferability of token is false, any kind of transfer of the token, save minting and burning, MUST revert execution.
In order to determine whether a token is mintable, the exception SHOULD be made to allow the tokenId parameter for a token that does not exist. Additionally the from parameter SHOULD be 0x0000000000000000000000000000000000000000 and the to parameter SHOULD NOT be 0x0000000000000000000000000000000000000000.
In order to determine whether a token is burnable, the from parameter SHOULD NOT be 0x0000000000000000000000000000000000000000 and the to parameter SHOULD be 0x0000000000000000000000000000000000000000.
Implementers MAY choose to validate the approval of the token for transfer by the from parameter, but anyone interacting with this function SHOULD NOT rely on it as it is not mandated by the proposal. This means that the from parameter in such implementations validates the initiator of the transaction rather than the owner from which the token is being transferred (which can either be the owner of the token or the operator allowed to transfer the token).'}

{'Main Content': 'The key words “MUST”, “MUST NOT”, “REQUIRED”, “SHALL”, “SHALL NOT”, “SHOULD”, “SHOULD NOT”, “RECOMMENDED”, “NOT RECOMMENDED”, “MAY”, and “OPTIONAL” in this document are to be interpreted as described in RFC 2119 and RFC 8174.', 'Redeem and Cancel Functions': 'An operator SHALL only make an update to the redemption created by itself. Therefore, the redeem() and cancel() functions do not have an _operator parameter, and the msg.sender address MUST be used as the _operator.', 'Redemption Flag Key-Value Pairs': 'The combination of _operator, _tokenId, and _redemptionId MUST be used as the key in the redemption flag key-value pairs, whose value can be accessed from the isRedeemed() function.
Every contract compliant with this EIP MUST implement ERC6672 and ERC721 interfaces.
pragma solidity ^0.8.16;

/// @title ERC-6672 Multi-Redeemable NFT Standard
/// @dev See https://eips.ethereum.org/EIPS/eip-6672
/// Note: the ERC-165 identifier for this interface is 0x4dddf83f.
interface IERC6672 /* is IERC721 */ {
    /// @dev This event emits when an NFT is redeemed.
    event Redeem(
        address indexed _operator,
        uint256 indexed _tokenId,
        address redeemer,
        bytes32 _redemptionId,
        string _memo
    );

    /// @dev This event emits when a redemption is canceled.
    event Cancel(
      address indexed _operator,
      uint256 indexed _tokenId,
      bytes32 _redemptionId,
      string _memo
    );

    /// @notice Check whether an NFT is already used for redemption or not.
    /// @dev 
    /// @param _operator The address of the operator of the redemption platform.
    /// @param _redemptionId The identifier for a redemption.
    /// @param _tokenId The identifier for an NFT.
    /// @return Whether an NFT is already redeemed or not.
    function isRedeemed(address _operator, bytes32 _redemptionId, uint256 _tokenId) external view returns (bool);

    /// @notice List the redemptions created by the given operator for the given NFT.
    /// @dev
    /// @param _operator The address of the operator of the redemption platform.
    /// @param _tokenId The identifier for an NFT.
    /// @return List of redemptions of speficic `_operator` and `_tokenId`.
    function getRedemptionIds(address _operator, uint256 _tokenId) external view returns (bytes32[]);

    /// @notice Redeem an NFT
    /// @dev
    /// @param _redemptionId The identifier created by the operator for a redemption.
    /// @param _tokenId The NFT to redeem.
    /// @param _memo
    function redeem(bytes32 _redemptionId, uint256 _tokenId, string _memo) external;

    /// @notice Cancel a redemption
    /// @dev
    /// @param _redemptionId The redemption to cancel.
    /// @param _tokenId The NFT to cancel the redemption.
    /// @param _memo
    function cancel(bytes32 _redemptionId, uint256 _tokenId, string _memo) external;
}', 'Metadata Extension': 'The key format for the redemptions key-value pairs MUST be standardized as operator-tokenId-redemptionId, where operator is the operator wallet address, tokenId is  the identifier of the token that has been redeemed, and redemptionId is the redemption identifier. The value of the key operator-tokenId-redemptionId is an object that contains the status and description of the redemption.
• Redemption status, i.e. status
The redemption status can have a more granular level, rather than just being a flag with a true or false value. For instance, in cases of physical goods redemption, we may require the redemption status to be either redeemed, paid, or shipping. It is RECOMMENDED to use a string enum that is comprehensible by both the operator and the marketplace or any other parties that want to exhibit the status of the redemption.
• Description of the redemption, i.e. description
The description SHOULD be used to provide more details about the redemption, such as information about the concert ticket, a detailed description of the action figures, and more.
The metadata extension is OPTIONAL for ERC-6672 smart contracts (see “caveats”, below). This allows your smart contract to be interrogated for its name and for details about the assets which your NFTs represent.
/// @title ERC-6672 Multi-Redeemable Token Standard, optional metadata extension
/// @dev See https://eips.ethereum.org/EIPS/eip-6672
interface IERC6672Metadata /* is IERC721Metadata */ {
    /// @notice A distinct Uniform Resource Identifier (URI) for a given asset.
    /// @dev Throws if `_tokenId` is not a valid NFT. URIs are defined in RFC
    ///  3986. The URI may point to a JSON file that conforms to the "ERC-6672
    ///  Metadata JSON Schema".
    function tokenURI(uint256 _tokenId) external view returns (string);
}
This is the “ERC-6672 Metadata JSON Schema” referenced above.
{
    "title": "Asset Metadata",
    "type": "object",
    "properties": {
        "name": {
            "type": "string",
            "description": "Identifies the asset to which this NFT represents"
        },
        "description": {
            "type": "string",
            "description": "Describes the asset to which this NFT represents"
        },
        "image": {
            "type": "string",
            "description": "A URI pointing to a resource with mime type image/* representing the asset to which this NFT represents. Consider making any images at a width between 320 and 1080 pixels and aspect ratio between 1.91:1 and 4:5 inclusive."
        }
    },
    "redemptions": {
        "operator-tokenId-redemptionId": {
            "status": {
                "type": "string",
                "description": "The status of a redemption. Enum type can be used to represent the redemption status, such as redeemed, shipping, paid."
            },
            "description": {
                "type": "string",
                "description": "Describes the object that has been redeemed for an NFT, such as the name of an action figure series name or the color of the product."
            }
        }
    }
}'}

{'IKBT20 (Token Contract)': 'NOTES:
• The following specifications use syntax from Solidity 0.8.0 (or above)
• Callers MUST handle false from returns (bool success). Callers MUST NOT assume that false is never returned!
interface IKBT20 {
    event AccountSecured(address _account, uint256 _amount);
    event AccountResetBinding(address _account);
    event SafeFallbackActivated(address _account);
    event AccountEnabledTransfer(
        address _account,
        uint256 _amount,
        uint256 _time,
        address _to,
        bool _allFunds
    );
    event AccountEnabledApproval(
        address _account,
        uint256 _time,
        uint256 _numberOfTransfers
    );
    event Ingress(address _account, uint256 _amount);
    event Egress(address _account, uint256 _amount);

    struct AccountHolderBindings {
        address firstWallet;
        address secondWallet;
    }

    struct FirstAccountBindings {
        address accountHolderWallet;
        address secondWallet;
    }

    struct SecondAccountBindings {
        address accountHolderWallet;
        address firstWallet;
    }

    struct TransferConditions {
        uint256 amount;
        uint256 time;
        address to;
        bool allFunds;
    }

    struct ApprovalConditions {
        uint256 time;
        uint256 numberOfTransfers;
    }

    function addBindings(
        address _keyWallet1,
        address _keyWallet2
    ) external returns (bool);

    function getBindings(
        address _account
    ) external view returns (AccountHolderBindings memory);

    function resetBindings() external returns (bool);

    function safeFallback() external returns (bool);

    function allowTransfer(
        uint256 _amount,
        uint256 _time,
        address _to,
        bool _allFunds
    ) external returns (bool);

    function getTransferableFunds(
        address _account
    ) external view returns (TransferConditions memory);

    function allowApproval(
        uint256 _time,
        uint256 _numberOfTransfers
    ) external returns (bool);

    function getApprovalConditions(
        address account
    ) external view returns (ApprovalConditions memory);

    function getNumberOfTransfersAllowed(
        address _account,
        address _spender
    ) external view returns (uint256);

    function isSecureWallet(address _account) external view returns (bool);
}', 'Events': '', 'AccountSecured event': 'Emitted when the _account is securing his account by calling the addBindings function.
_amount is the current balance of the _account.
event AccountSecured(address _account, uint256 _amount)', 'AccountResetBinding event': 'Emitted when the holder is resetting his keyWallets by calling the resetBindings function.
event AccountResetBinding(address _account)', 'SafeFallbackActivated event': 'Emitted when the holder is choosing to move all the funds to one of the keyWallets by calling the safeFallback function.
event SafeFallbackActivated(address _account)', 'AccountEnabledTransfer event': 'Emitted when the _account has allowed for transfer an _amount of tokens for the _time amount of block seconds for _to address (or if
the _account has allowed for transfer all funds though _allFunds set to true) by calling the allowTransfer function.
event AccountEnabledTransfer(address _account, uint256 _amount, uint256 _time, address _to, bool _allFunds)', 'AccountEnabledApproval event': 'Emitted when _account has allowed approval, for the _time amount of block seconds and set a _numberOfTransfers allowed, by calling the allowApproval function.
event AccountEnabledApproval(address _account, uint256 _time, uint256 _numberOfTransfers)', 'Ingress event': 'Emitted when _account becomes a holder. _amount is the current balance of the _account.
event Ingress(address _account, uint256 _amount)', 'Egress event': 'Emitted when _account transfers all his tokens and is no longer a holder. _amount is the previous balance of the _account.
event Egress(address _account, uint256 _amount)', 'Interface functions': 'The functions detailed below MUST be implemented.', 'addBindings function': 'Secures the sender account with other two wallets called _keyWallet1 and _keyWallet2 and MUST fire the AccountSecured event.
The function SHOULD revert if:
• the sender account is not a holder
• or the sender is already secured
• or the keyWallets are the same
• or one of the keyWallets is the same as the sender
• or one or both keyWallets are zero address (0x0)
• or one or both keyWallets are already keyWallets to another holder account
function addBindings (address _keyWallet1, address _keyWallet2) external returns (bool)', 'getBindings function': 'The function returns the keyWallets for the _account in a struct format.
struct AccountHolderBindings {
    address firstWallet;
    address secondWallet;
}
function getBindings(address _account) external view returns (AccountHolderBindings memory)', 'resetBindings function': 'Note: This function is helpful when one of the two keyWallets is compromised.
Called from a keyWallet, the function resets the keyWallets for the holder account. MUST fire the AccountResetBinding event.
The function SHOULD revert if the sender is not a keyWallet.
function resetBindings() external returns (bool)', 'safeFallback function': 'Note: This function is helpful when the holder account is compromised.
Called from a keyWallet, this function transfers all the tokens from the holder account to the other keyWallet and MUST fire the SafeFallbackActivated event.
The function SHOULD revert if the sender is not a keyWallet.
function safeFallback() external returns (bool);', 'allowTransfer function': 'Called from a keyWallet, this function is called before a transfer function is called.
It allows to transfer a maximum amount, for a specific time frame, to a specific address.
If the amount is 0 then there will be no restriction on the amount.
If the time is 0 then there will be no restriction on the time.
If the to address is zero address then there will be no restriction on the to address.
Or if _allFunds is true, regardless of the other params, it allows all funds, whenever, to anyone to be transferred.
The function MUST fire AccountEnabledTransfer event.
The function SHOULD revert if the sender is not a keyWallet or if the _amount is greater than the holder account balance.
function allowTransfer(uint256 _amount, uint256 _time, address _to, bool _allFunds) external returns (bool);', 'getTransferableFunds function': 'The function returns the transfer conditions for the _account in a struct format.
struct TransferConditions {
    uint256 amount;
    uint256 time;
    address to;
    bool allFunds;
}
function getTransferableFunds(address _account) external view returns (TransferConditions memory);', 'allowApproval function': 'Called from a keyWallet, this function is called before one of the approve, increaseAllowance or decreaseAllowance function are called.
It allows the holder for a specific amount of _time to do an approve, increaseAllowance or decreaseAllowance and limit the number of transfers the spender is allowed to do through _numberOfTransfers (0 - unlimited number of transfers in the allowance limit).
The function MUST fire AccountEnabledApproval event.
The function SHOULD revert if the sender is not a keyWallet.
function allowApproval(uint256 _time, uint256 _numberOfTransfers) external returns (bool)', 'getApprovalConditions function': 'The function returns the approval conditions in a struct format. Where time is the block.timestamp until the approve, increaseAllowance or decreaseAllowance functions can be called, and numberOfTransfers is the number of transfers the spender will be allowed.
struct ApprovalConditions {
    uint256 time;
    uint256 numberOfTransfers;
}
function getApprovalConditions(address _account) external view returns (ApprovalConditions memory);', 'transfer function': 'The function transfers _amount of tokens to address _to.
The function MUST fire the Transfer event.
The function SHOULD revert if the sender’s account balance does not have enough tokens to spend, or if the sender is a secure account and it has not allowed the transfer of funds through allowTransfer function.
Note: Transfers of 0 values MUST be treated as normal transfers and fire the Transfer event.
function transfer(address _to, uint256 _amount) external returns (bool)', 'approve function': 'The function allows _spender to transfer from the holder account multiple times, up to the _value amount.
The function also limits the _spender to the specific number of transfers set in the ApprovalConditions for that holder account. If the value is 0 then the _spender can transfer multiple times, up to the _value amount.
The function MUST fire an Approval event.
If this function is called again it overrides the current allowance with _value and also overrides the number of transfers allowed with _numberOfTransfers, set in allowApproval function.
The function SHOULD revert if:
• the sender account is secured and has not called allowApproval function
• or if the _time, set in the allowApproval function, has elapsed.
function approve(address _spender, uint256 _amount) external returns (bool)', 'increaseAllowance function': 'The function increases the allowance granted to _spender to withdraw from your account.
The function Emits an Approval event indicating the updated allowance.
The function SHOULD revert if:
• the sender account is secured and has not called allowApproval function
• or if the _spender is a zero address (0x0)
• or if the _time, set in the allowApproval function, has elapsed.
function increaseAllowance(address _spender, uint256 _addedValue) external returns (bool)', 'decreaseAllowance function': 'The function decreases the allowance granted to _spender to withdraw from your account.
The function Emits an Approval event indicating the updated allowance.
The function SHOULD revert if:
• the sender account is secured and has not called allowApproval function
• or if the _spender is a zero address (0x0)
• or if the _time, set in the allowApproval function, has elapsed.
• or if the _subtractedValue is greater than the current allowance
function decreaseAllowance(address _spender, uint256 _subtractedValue) external returns (bool)', 'transferFrom function': 'The function transfers _amount of tokens from address _from to address _to.
The function MUST fire the Transfer event.
The transferFrom method is used for a withdraw workflow, allowing contracts to transfer tokens on your behalf.
The function SHOULD revert unless the _from account has deliberately authorized the sender.
Each time the spender calls the function the contract subtracts and checks if the number of allowed transfers has reached 0,
and when that happens the approval is revoked using an approve of 0 amount.
Note: Transfers of 0 values MUST be treated as normal transfers and fire the Transfer event.
function transferFrom(address _from, address _to, uint256 _amount) external returns (bool)'}

